import React, { useState } from 'react';
import { API } from '../config';
import './UserPanel.css';   // ✅ import the CSS file

function UserPanel({ setUserToken, userToken }) {
  const [form, setForm] = useState({});
  const [myChallans, setMyChallans] = useState([]);

  async function signup(e) {
    e.preventDefault();
    const res = await fetch(API + '/user/signup', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(form)
    });
    const data = await res.json();
    alert(data.message || 'Signup successful');
  }

  async function login(e) {
    e.preventDefault();
    const res = await fetch(API + '/user/login', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ email: form.email, password: form.password })
    });
    const data = await res.json();
    if (data.token) {
      setUserToken(data.token);
      localStorage.setItem('uid', data.userId);
      alert('Logged in');
      fetchMine(data.userId);
    } else {
      alert(data.message || 'Error');
    }
  }

  async function fetchMine(userId) {
    const id = userId || localStorage.getItem('uid');
    if (!id) return alert('No user id');
    const res = await fetch(API + '/challan/user/' + id);
    const data = await res.json();
    setMyChallans(data);
  }

  async function pay(challanId) {
    const res = await fetch(API + '/challan/pay/' + challanId, { method: 'POST' });
    const data = await res.json();
    alert(data.message || 'Paid');
    fetchMine();
  }

  return (
    <div className="user-panel">
      <h2>User Panel</h2>

      <div className="forms-container">
        {/* Signup Form */}
        <form onSubmit={signup} className="form-card">
          <h4>Signup</h4>
          <input placeholder="Name" onChange={e => setForm({ ...form, name: e.target.value })} />
          <input placeholder="Email" onChange={e => setForm({ ...form, email: e.target.value })} />
          <input placeholder="Vehicle Number" onChange={e => setForm({ ...form, vehicleNumber: e.target.value })} />
          <input type="password" placeholder="Password" onChange={e => setForm({ ...form, password: e.target.value })} />
          <button>Signup</button>
        </form>

        {/* Login Form */}
        <form onSubmit={login} className="form-card">
          <h4>Login</h4>
          <input placeholder="Email" onChange={e => setForm({ ...form, email: e.target.value })} />
          <input type="password" placeholder="Password" onChange={e => setForm({ ...form, password: e.target.value })} />
          <button>Login</button>
        </form>
      </div>

      {/* Challans Table */}
      <div className="challans-section">
        <h3>My Challans</h3>
        <button onClick={() => fetchMine()} className="refresh-btn">Refresh</button>
        <table className="challans-table">
          <thead>
            <tr>
              <th>#</th>
              <th>Vehicle</th>
              <th>Cause</th>
              <th>Fine</th>
              <th>Status</th>
              <th>Action</th>
            </tr>
          </thead>
          <tbody>
            {myChallans.map((c, i) => (
              <tr key={c._id}>
                <td>{i + 1}</td>
                <td>{c.vehicleNumber}</td>
                <td>{c.cause}</td>
                <td>{c.fine}</td>
                <td>{c.status}</td>
                <td>
                  {c.status !== 'Paid' && (
                    <button onClick={() => pay(c._id)} className="pay-btn">Pay</button>
                  )}
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    </div>
  );
}

export default UserPanel;
